<script setup>
import { computed } from 'vue';
import NumberField from './NumberField.vue';
import { currency } from '../data/laborCatalog';
import { defaultPromotionSettings, paymentSummary } from '../services/promotions';
const props = defineProps({ modelValue: Object, defaults: { type: Object, default: defaultPromotionSettings }, total: Number });
const emit = defineEmits(['update:modelValue']);
const summary = computed(() => { try { return paymentSummary(props.total, props.modelValue); } catch { return null; } });
function discount(value) { emit('update:modelValue', { ...props.modelValue, discountPercent: value }); }
function toggle(plan, enabled) { emit('update:modelValue', { ...props.modelValue, installments: enabled ? [...props.modelValue.installments, { ...plan }] : props.modelValue.installments.filter(p => p.count !== plan.count) }); }
function surcharge(count, value) { emit('update:modelValue', { ...props.modelValue, installments: props.modelValue.installments.map(p => p.count === count ? { ...p, surchargePercent: value } : p) }); }
</script>
<template><section class="budget-promotions" aria-labelledby="payment-title"><h3 id="payment-title">Promociones en el PDF</h3><p>Elegí las alternativas de pago para este cliente. Son opciones: los recargos no se suman entre sí ni modifican el total de mano de obra.</p><div class="catalog-fields"><label>Descuento al contado (%)<NumberField :model-value="modelValue.discountPercent" @update:model-value="discount" :min="0" :max="100" :step="0.1" aria-label="Descuento al contado del presupuesto" /></label><button v-if="defaults.discountPercent > 0" type="button" @click="discount(defaults.discountPercent)">Usar descuento configurado ({{ defaults.discountPercent }} %)</button></div><div v-for="preset in defaults.installments" :key="preset.count" class="payment-plan"><label><input type="checkbox" :checked="modelValue.installments.some(p => p.count === preset.count)" @change="toggle(preset, $event.target.checked)" :aria-label="'Incluir ' + preset.count + ' cuotas en PDF'" /> Mostrar {{ preset.count }} cuotas</label><label v-if="modelValue.installments.some(p => p.count === preset.count)">Recargo (%)<NumberField :model-value="modelValue.installments.find(p => p.count === preset.count).surchargePercent" @update:model-value="surcharge(preset.count, $event)" :min="0" :max="1000" :step="0.1" :aria-label="'Recargo ' + preset.count + ' cuotas del presupuesto'" /></label></div><p v-if="summary?.discountPercent">Contado: {{ currency(summary.cashTotal) }} ({{ summary.discountPercent }} % de descuento).</p><ul v-if="summary?.plans.length"><li v-for="plan in summary.plans" :key="plan.count">{{ plan.count }} cuotas · {{ plan.surchargePercent }} % de recargo · Total {{ currency(plan.total) }}<span v-if="plan.installment === plan.lastInstallment"> · {{ currency(plan.installment) }} cada una</span><span v-else> · {{ plan.count - 1 }} de {{ currency(plan.installment) }} y última de {{ currency(plan.lastInstallment) }}</span></li></ul><p v-if="!summary" role="alert">Revisá los porcentajes antes de guardar o descargar.</p><RouterLink to="/config">Configurar mis promociones</RouterLink></section></template>
<style scoped>.budget-promotions{margin:22px 0;padding:18px;border:1px solid #475366;border-radius:8px}.payment-plan{display:flex;align-items:center;gap:20px;flex-wrap:wrap;margin:10px 0}.payment-plan>label:first-child{display:flex;gap:10px;align-items:center}.payment-plan input[type=checkbox]{width:18px;min-height:18px}</style>
